package dev.wave.util;

import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.render.RenderLayer;
import net.minecraft.client.util.math.MatrixStack;
import net.minecraft.util.Identifier;

import java.util.HashMap;
import java.util.Map;

/** Custom icon atlas (generated by tools/gen_icons.py). Icons are white and tinted at draw time. */
public final class Icons {
    private Icons() {}

    private static final Identifier ATLAS = Identifier.of("waveclient", "textures/icons.png");
    private static final int CELL = 48, COLS = 8, TEX_W = 384, TEX_H = 240;
    private static final String[] NAMES = {
            "visuals", "movement", "player", "hud", "client", "fullbright", "esp", "tracers", "storageesp", "zoom",
            "crosshair", "nohurtcam", "nooverlay", "ambience", "sprint", "autowalk", "parkour", "eagle", "autorespawn",
            "antiafk", "watermark", "arraylist", "info", "coordinates", "armor", "potions", "keystrokes", "inventory",
            "clickgui", "notifications", "hudeditor", "search", "back", "power", "check", "close", "arrow", "toggle"};
    private static final Map<String, Integer> INDEX = new HashMap<>();
    private static boolean filtered;

    static {
        for (int i = 0; i < NAMES.length; i++) INDEX.put(NAMES[i], i);
    }

    public static String key(String name) { return name.toLowerCase().replace(" ", ""); }

    public static void draw(DrawContext c, String name, float x, float y, float size, int color) {
        Integer idx = INDEX.get(key(name));
        if (idx == null) idx = INDEX.get("toggle");
        color = ColorUtil.alpha(color, RenderUtil.globalAlpha);
        if (ColorUtil.getAlpha(color) < 4) return;
        if (!filtered) {
            MinecraftClient.getInstance().getTextureManager().getTexture(ATLAS).setFilter(true, false);
            filtered = true;
        }
        int u = (idx % COLS) * CELL, v = (idx / COLS) * CELL;
        MatrixStack m = c.getMatrices();
        m.push();
        m.translate(x, y, 0);
        float s = size / CELL;
        m.scale(s, s, 1);
        c.drawTexture(RenderLayer::getGuiTextured, ATLAS, 0, 0, u, v, CELL, CELL, CELL, CELL, TEX_W, TEX_H, color);
        m.pop();
    }
}
